contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function: caller sends some value to addToBalance and then we assert
    // that the recorded balance for this contract is >= the value we just sent.
    // This holds for the original (which adds msg.value) but is violated by the mutant (which assigns msg.value, losing prior funds).
    function run(uint256 priorAmount, uint256 sendAmount) public payable {
        // ensure this test contract has enough balance to send
        require(address(this).balance >= sendAmount + priorAmount);

        // Optionally seed a prior balance by calling addToBalance with priorAmount
        if (priorAmount > 0) {
            c.addToBalance{value: priorAmount}();
        }

        // perform the deciding call: send sendAmount
        c.addToBalance{value: sendAmount}();

        // observe the stored balance for this contract
        uint256 recorded = c.getBalance(address(this));

        // property: after sending sendAmount, the recorded balance is at least sendAmount
        // (i.e., the call does not make the stored balance smaller than the amount just sent)
        assert(recorded >= sendAmount);
    }

    // allow receiving ether to fund the contract for tests
    receive() external payable {}
}

