contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: actor (who will perform the addToBalance) and a prior actor otherAcct
    // and amounts: priorBalance for otherAcct, and payAmount sent by actor.
    function testFuzz_property(address actor, address otherAcct, uint256 priorBalance, uint256 payAmount) public {
        // Keep addresses non-zero to be meaningful; allow actor == otherAcct (admissible)
        vm.assume(actor != address(0));
        vm.assume(otherAcct != address(0));
        // Bound amounts to a reasonable range and ensure payAmount fits in balance
        payAmount = bound(payAmount, 0, 1 ether);
        priorBalance = bound(priorBalance, 0, 1 ether);

        // Arrange: give otherAcct a prior balance via actor-independent deposit
        // We'll deposit into otherAcct by impersonating otherAcct
        if (priorBalance > 0) {
            vm.deal(otherAcct, priorBalance);
            vm.prank(otherAcct);
            // deposit priorBalance into otherAcct's userBalance
            c.addToBalance{value: priorBalance}();
        }

        // Record otherAcct's balance before actor's operation
        uint256 beforeOther = c.getBalance(otherAcct);

        // Fund actor and have actor call addToBalance with payAmount
        if (payAmount > 0) {
            vm.deal(actor, payAmount);
            vm.prank(actor);
            c.addToBalance{value: payAmount}();
