        // That is, otherAcct's balance after actor's deposit should equal beforeOther.
        // This holds for the correct contract for all inputs; the mutant that assigns userBalance[msg.sender] = msg.value
        // can cause balances to differ when actor == otherAcct and prior balance was nonzero.
        uint256 afterOther = c.getBalance(otherAcct);
        assertTrue(afterOther == beforeOther);
    }
