pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz over a caller and an amount. We keep domain wide: amount up to 1 ether.
    function testFuzz_property(address actor, uint256 amount) public {
        // wide bounds: amount at most 1 ether to keep tx feasible
        amount = bound(amount, 0, 1 ether);

        // fund the actor so they can send value
        vm.deal(actor, amount);

        // Record contract balance and total stored balance before
        uint256 beforeContractBal = address(c).balance;

        // We cannot iterate all addresses; but observe that the contract invariant in correct
        // implementation is: address(c).balance == sum of userBalance for all addresses.
        // We will check this equality both before and after the call. The mutant will break it
        // for some inputs because it decreases stored balances while contract's ETH increases.

        // check invariant holds initially
        // Since everything starts zero, and we haven't interacted, invariant holds: both zero.
        // Make the call as actor, sending amount.
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // After the call, for the correct contract, address(c).balance equals the sum of stored balances.
        // We assert that address(c).balance is at least beforeContractBal (non-decreasing) and that
        // address(c).balance equals itself (single observable) — but to capture the bug we assert
        // that the contract's Ether balance did not exceed the sum of stored balances. We only have
        // access to address(c).balance; however, the correct contract ensures equality between
        // address(c).balance and the total of stored userBalance. The mutant can cause stored total
        // to drop while address(c).balance increases, violating "address(c).balance <= sum of stored balances".

        // Since we cannot read the entire mapping, we instead assert that address(c).balance >= beforeContractBal
        // and that the call did not decrease the contract-observed invariant: address(c).balance == address(c).balance
        // To make a meaningful single assertion over c's public surface that the reference satisfies always
        // and mutant violates for some inputs, we assert that calling getBalance(actor) after the call is >= 0
        // which is trivially true for both; that would not distinguish. Instead, we use try/catch on addToBalance
        // to detect if the call reverted. In the correct contract it will never revert for funded actor; the mutant
        // also likely won't revert (but state differs). Therefore we craft an assertion on address(c).balance being == beforeContractBal + amount.
        // In the reference, after a successful addToBalance the contract's ETH balance equals before + amount.
        // The mutant also receives ETH, so address(c).balance will be equal as well. To distinguish, we assert that
        // address(c).balance == beforeContractBal + amount AND that getBalance(actor) == amount.
        // This combined single assert ensures the stored balance reflects the sent amount for the caller —
        // the reference satisfies this for all inputs; the mutant that subtracts msg.value will make getBalance(actor) underflow to huge value in 0.8 which reverts; to keep domain wide we allow amount==0 too.

        // Retrieve stored balance for actor via getter
        uint256 stored = c.getBalance(actor);
        uint256 afterContractBal = address(c).balance;

        // Single assertion over c's public surface: after deposit, contract balance equals prior + amount
        // and caller's stored balance equals amount. The reference satisfies this for all inputs; the mutant
        // will in some cases make stored != amount (or revert) and thus fail this assertion.
        assertTrue(afterContractBal == beforeContractBal + amount && stored == amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller deposits amt and we assert their recorded balance increased by amt
    function runTest(address depositor, uint256 amt) public payable {
        // ensure this contract has enough balance to forward
        require(address(this).balance >= amt, "insufficient ether in tester");
        // precondition: depositor is an EOA or contract; we only use c's public surface
        uint256 before = c.getBalance(depositor);
        // perform the deposit: call addToBalance as if msg.sender is this contract
        // to make depositor be the msg.sender for c, we need to have this contract send the call
        // but caller identity seen by c will be this contract, not the passed 'depositor' param.
        // To satisfy the specification, we instead interpret 'depositor' as the caller whose balance we check
        // and require that depositor == address(this) to make msg.sender == depositor when calling c.
        // Express this as a precondition so the assertion is meaningful for general inputs.
        require(depositor == address(this), "depositor must be this contract to be msg.sender for c");

        // make the deposit: this contract calls c.addToBalance forwarding amt
        c.addToBalance{value: amt}();

        uint256 after = c.getBalance(depositor);
        // On the original contract P, addToBalance uses msg.sender, so the balance for depositor (this) increases by amt.
        // On the mutant M, addToBalance updates userBalance[tx.origin] instead, so when tx.origin != msg.sender (common),
        // the balance for depositor (this) will NOT increase by amt, violating the assertion.
        assert(after == before + amt);
    }

    // allow this contract to receive Ether for forwarding
    receive() external payable {}
}

