import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor is the immediate caller (msg.sender), originator is tx.origin
    // We fuzz two addresses and an amount. The rule requires that after the call,
    // userBalance[depositor] increases by amount. The mutant writes to tx.origin instead,
    // so when depositor != originator the mutant will not update depositor's balance.
    function testFuzz_property(address depositor, address originator, uint256 amount) public {
        // Keep addresses non-zero and distinct to expose the bug (but allow many inputs).
        vm.assume(depositor != address(0));
        vm.assume(originator != address(0));
        // We want cases where depositor != originator so the mutant mis-updates a different key.
        vm.assume(depositor != originator);

        // bound the amount to a reasonable range to avoid issues with vm.deal
        amount = bound(amount, 1, 1 ether);

        // Fund the originator because the call will originate from originator, and the depositor will be msg.sender
        // To simulate tx.origin != msg.sender, deploy a simple forwarder contract from originator which will call c
        vm.deal(originator, amount + 1 ether);

        // deploy a forwarder contract with tx.origin == originator and which will call c as msg.sender = forwarder
        vm.prank(originator);
        Forwarder f = new Forwarder();

        // Give the forwarder some ETH so it can forward the deposit
        vm.deal(address(f), amount);

        // The forwarder will perform a call where msg.sender == address(f) and tx.origin == originator.
        // We want msg.sender (the immediate caller) to be `depositor`, so we need the forwarder to delegatecall
        // or have the depositor be the forwarder. Instead, to make msg.sender == depositor and tx.origin == originator,
        // we can have the forwarder call into a helper which uses tx.origin as the originator of the outer tx.
        // Simpler approach: make depositor be the forwarder address chosen by the fuzz (i.e., depositor is an EOA),
        // but we must ensure tx.origin != depositor. To achieve that, we simulate a call chain: originator -> depositor(EOA) -> c.
        // Foundry cannot make an EOA call on behalf of another EOA, but we can simulate by having originator deploy a helper
